      document.querySelectorAll(".accordion-item")?.forEach((i) => {
        i?.children[0]?.children[1]?.children[0]?.classList?.remove(
          "icon-angle-right-regular"
        );
        i?.children[0]?.children[1]?.children[0]?.classList?.add(
          "icon-angle-down-regular"
        );
        i.children[1].style.display = "flex";
        this.$emit("accordionopen");
      });
    }
