              // console.log(e.style.display);
              document.querySelectorAll(".accordion-content").forEach((e) => {
                e.style.display = "none";
              });
              e.classList.remove("icon-angle-down-regular");
              e.classList.add("icon-angle-right-regular");
            }
          });
