<template>

  <hlx-modal
    :modal-active="delete_modal_active"
    :height="'220px'"
    :width="'400px'"
    :modal="true"
    @close="delete_modal_active = false"
  >
    <template #header>
      <div style="margin-left: 0px">Delete email message</div>
    </template>
    <template #content>
      <div class="modal-content">
        <p>Are you sure you want to delete the email message ?</p>
      </div>
    </template>
    <template #footer>
      <hlx-button class="secondary sm" @click="delete_modal_active = false"
        >Cancel</hlx-button
      >
      <hlx-button
        class="primary sm"
        style="margin-left: 16px"
        @click="closeEmail"
        >Delete</hlx-button
      >
    </template>
  </hlx-modal>


  <hlx-modal
    :modal-active="valid_modal_active"
    :height="'220px'"
    :width="'400px'"
    :modal="true"
    @close="validationemail()"
  >
    <template #header>
      <div style="margin-left: 0px">Email Validation</div>
    </template>
    <template #content>
      <div class="modal-content">
        <p>{{`${combinedMessage}`}}</p>
      </div>
    </template>
    <template #footer>
     
      <hlx-button
        class="primary sm"
        style="margin-left: 16px"
        @click="validationemail()"
        >Ok</hlx-button
      >
    </template>
  </hlx-modal>
  <hlx-alert-notification
    :show-alert="alertmsg"
    :notify="notification"
    :auto-close="true"
  />

  <div>
    <div
      v-show="showEmailModal == true"
      class="email_overlay"
      :class="{ expandedEmail: isExpanded }"
    >
      <div class="emailCrudModal" :class="{ expandedCurdEmail: isExpanded }">
        <!-- header for email  -->
        <div class="email_head">
          <div class="email_head_name">New Message</div>
          <div style="display: flex; gap: 16px">
            <div class="expandedverstion" @click="toggleExpanded">
              <span v-if="isExpanded === false"
                ><i class="icon-arrows-expand-filled"></i
              ></span>
              <span v-if="isExpanded === true"
                ><i class="icon-arrows-compress-filled"></i
              ></span>
            </div>
            <div @click="closeEmail">
              <i class="icon-times-regular email_head_icone"></i>
            </div>
          </div>
        </div>
        <div class="height_fit_for_body">
          <div
            v-show="showAllEmail"
            class="email_cc showAllEmail"
            style="justify-content: flex-start; color: #000; font-size: 14px"
            @click="showToCcBcc"
          >
            {{ firstTwoValue }}
            <span
              v-if="moreValueToCc > 0 || moreValueBcc > 0"
              class="moredetail_email"
            >
              <span v-if="moreValueToCc > 0">{{ moreValueToCc + "more" }}</span>
              <span v-if="moreValueBcc > 0">{{ `(${moreValueBcc}Bcc)` }}</span>
            </span>
          </div>
          <!-- To CC Bcc subject for email  -->
          <div v-show="showTo" class="email_cc">
            <div class="email_cc_to">To:</div>
            <div class="email_input">
              <div class="tag-email-container">
                <div class="container">
                  <div v-for="(i, index) in displayValueTo" :key="index">
                    <span>
                      <span v-if="defaultContain && index === 0">
                        <hlx-label
                          class="primary"
                          :options="{
                            'background-color': '#54bd95',
                            'text-color': 'white',
                            'border-color': '#54bd95',
                          }"
                          >{{ i.name }}</hlx-label
                        >
                      </span>
                      <span v-else>
                        <hlx-tag
                          class="tagToEmail"
                          :limited="true"
                          @tag-close="
                            removed(
                              tagValueTo,
                              index,
                              allTagsValue,
                              displayValueTo
                            )
                          "
                          >{{ i.name }}</hlx-tag
                        >
                      </span>
                    </span>
                  </div>
                  <input
                    ref="inputFieldto"
                    v-model="toEmailInput"
                    type="email"
                    @keyup.enter="
                      addvalueArray(
                        tagValueTo,
                        toEmailInput,
                        'inputFieldto',
                        displayValueTo
                      )
                    "
                    @blur="
                      addvalueArray(
                        tagValueTo,
                        toEmailInput,
                        'inputFieldto',
                        displayValueTo
                      )
                    "
                  />
                </div>
                <div></div>
              </div>
            </div>
            <div
              class="email_cc__BCC_Cc"
              :style="{ display: showCc || showBcc ? 'none' : 'flex' }"
            >
              <span
                :style="{ display: showCc ? 'none' : 'block' }"
                class="email_cc_Cc"
                @click="showCc = true"
                >Cc</span
              >
              <span
                :style="{ display: showBcc ? 'none' : 'block' }"
                style="margin-left: 16px"
                class="email_cc_Bcc"
                @click="showBcc = true"
                >Bcc</span
              >
            </div>
          </div>

          <div
            v-show="showEmailDescriptionTo"
            ref="emailDescriptionTo"
            class="email_description_option postion_description_to"
          >
            <div
              v-for="(email, index) in filteredData"
              :key="index"
              class="email_options_container"
              @click="
                addvalueArray(
                  tagValueTo,
                  email.email,
                  'inputFieldto',
                  displayValueTo,
                  email
                )
              "
            >
              <div class="email_options">
                <span
                  ><hlx-file-upload
                    :key="componentkey"
                    :file-type="'.jpg,.jpeg,.png'"
                    :file-size-limit="'20mb'"
                    :uploadtype="'Circle'"
                    :style-background="backgrounStyleupload"
                    :height="32"
                    :width="32"
                    :read-only="true"
                    :custom-icon="icon"
                    :type="'profile-upload'"
                    :name-display="email?.name"
                    :content="'Import'"
                    @fileData="profiledata"
                /></span>
                <span
                  style="
                    padding: 6px;
                    display: flex;
                    flex-direction: column;
                    gap: 3px;
                  "
                >
                  <span>{{ email?.name }}</span>
                  <span style="font-size: 12px">{{ email?.email }}</span>
                </span>
              </div>
            </div>
          </div>

          <div v-show="showCc" class="email_cc">
            <div class="email_cc_to">CC:</div>
            <div class="email_input">
              <div class="tag-email-container">
                <div class="container">
                  <div v-for="(i, index) in displayValueCc" :key="index">
                    <hlx-tag
                      :limited="true"
                      @tag-close="
                        removed(tagValueCc, index, allTagsValue, displayValueCc)
                      "
                      >{{ i.name }}</hlx-tag
                    >
                  </div>
                  <input
                    ref="inputFieldcc"
                    v-model="ccEmailInput"
                    type="email"
                    class="email-input"
                    @keyup.enter.prevent="
                      addvalueArray(
                        tagValueCc,
                        ccEmailInput,
                        'inputFieldcc',
                        displayValueCc
                      )
                    "
                    @blur="
                      addvalueArray(
                        tagValueCc,
                        ccEmailInput,
                        'inputFieldcc',
                        displayValueCc
                      )
                    "
                  />
                </div>
                <div>
                  <!-- @input="adjustInputSize($event.target)" -->
                </div>
              </div>
            </div>
            <span
              :style="{ display: showBcc ? 'none' : 'block' }"
              style="margin-left: 16px"
              class="email_cc_Bcc"
              @click="showBcc = true"
              >Bcc</span
            >
          </div>
          <div
            v-show="showEmailDescriptionCc"
            ref="emailDescriptionCc"
            class="email_description_option postion_description_cc"
          >
            <div
              v-for="(email, index) in filteredData"
              :key="index"
              class="email_options_container"
              @click="
                addvalueArray(
                  tagValueCc,
                  email.email,
                  'inputFieldcc',
                  displayValueCc,
                  email
                )
              "
            >
              <div class="email_options">
                <span
                  ><hlx-file-upload
                    :key="componentkey"
                    :file-type="'.jpg,.jpeg,.png'"
                    :file-size-limit="'20mb'"
                    :uploadtype="'Circle'"
                    :style-background="backgrounStyleupload"
                    :height="32"
                    :width="32"
                    :read-only="true"
                    :custom-icon="icon"
                    :type="'profile-upload'"
                    :name-display="email?.name"
                    :content="'Import'"
                    @fileData="profiledata"
                /></span>
                <span
                  style="
                    padding: 6px;
                    display: flex;
                    flex-direction: column;
                    gap: 3px;
                  "
                >
                  <span>{{ email?.name }}</span>
                  <span style="font-size: 12px">{{ email?.email }}</span>
                </span>
              </div>
            </div>
          </div>
          <div v-show="showBcc" class="email_cc">
            <div class="email_cc_to">Bcc:</div>
            <div class="email_input">
              <div class="tag-email-container">
                <div class="container">
                  <div v-for="(i, index) in displayValueBcc" :key="index">
                    <hlx-tag
                      :limited="true"
                      @tag-close="
                        removed(
                          tagValueBcc,
                          index,
                          allTagsValue,
                          displayValueBcc
                        )
                      "
                      >{{ i.name }}</hlx-tag
                    >
                  </div>
                  <input
                    ref="inputFieldbcc"
                    v-model="bccEmailInput"
                    type="email"
                    class="email-input"
                    @keyup.enter.prevent="
                      addvalueArray(
                        tagValueBcc,
                        bccEmailInput,
                        'inputFieldbcc',
                        displayValueBcc
                      )
                    "
                    @blur="
                      addvalueArray(
                        tagValueBcc,
                        bccEmailInput,
                        'inputFieldbcc',
                        displayValueBcc
                      )
                    "
                  />
                </div>
                <div>
                  <!-- @input="adjustInputSize($event.target)" -->
                </div>
              </div>
            </div>
            <span
              :style="{ display: showCc ? 'none' : 'block' }"
              class="email_cc_Cc"
              @click="showCc = true"
              >Cc</span
            >
          </div>
          <div
            v-show="showEmailDescriptionBcc"
            ref="emailDescriptionBcc"
            class="email_description_option postion_description_bcc"
          >
            <div
              v-for="(email, index) in filteredData"
              :key="index"
              class="email_options_container"
              @click="
                addvalueArray(
                  tagValueBcc,
                  email.email,
                  'inputFieldbcc',
                  displayValueBcc,
                  email
                )
              "
            >
              <div class="email_options">
                <span
                  ><hlx-file-upload
                    :key="componentkey"
                    :file-type="'.jpg,.jpeg,.png'"
                    :file-size-limit="'20mb'"
                    :uploadtype="'Circle'"
                    :style-background="backgrounStyleupload"
                    :height="32"
                    :width="32"
                    :read-only="true"
                    :custom-icon="icon"
                    :type="'profile-upload'"
                    :name-display="email?.name"
                    :content="'Import'"
                    @fileData="profiledata"
                /></span>
                <span
                  style="
                    padding: 6px;
                    display: flex;
                    flex-direction: column;
                    gap: 3px;
                  "
                >
                  <span>{{ email?.name }}</span>
                  <span style="font-size: 12px">{{ email?.email }}</span>
                </span>
              </div>
            </div>
          </div>
          <div
            class="email_subject"
            @click="
              concatEmail(displayValueTo, displayValueCc, displayValueBcc)
            "
          >
            <div class="email_input" style="margin: 0 10px 0 0">
              <input
                v-model="subjectEmailInput"
                type="text"
                placeholder="Subject"
              />
            </div>
            <!-- @input="adjustInputSize($event.target)" -->
          </div>
        </div>
        <!-- body text-editor component for email -->
        <div
          class="attachmeny_email_"
          style="max-height: 517px; overflow: auto"
        >
          <div
            class="email_text_editor_body"
            @click="
              concatEmail(displayValueTo, displayValueCc, displayValueBcc)
            "
          >
            <hlx-text-editor
              :key="componentKey"
              v-model="bodyContentv"
              :email-component="true"
              :border="false"
              @current-change="handleCurrentChange"
            ></hlx-text-editor>
          </div>

          <div
            v-if="filesArrayData.length > 0"
            class="box-attachment-supplier-parent-email"
          >
            <div
              v-for="(box, index) in filesArrayData"
              :key="index"
              class="box-attachment-supplier"
            >
              <span class="closeIconeSupplier" @click="handleClose(box, index)"
                ><i style="color: #6e6b7b" class="icon-trash-regular"></i
              ></span>
              <div>
                <span
                  v-if="getFileExtension(box.properties.name) === 'txt'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/text.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'docx'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/word.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'png'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/png.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'pdf'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/pdf.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'json'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/json.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'jpg'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/jpg.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'jpeg'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/jpeg.svg"
                    alt=""
                /></span>
                <span
                  v-if="getFileExtension(box.properties.name) === 'xlsx'"
                  class="upload_component_icon"
                  ><img
                    class="file-icon"
                    src="https://cdn.halleyx-dm.com/ui-kit-assests/assets/svg/multiUpload/excel.svg"
                    alt=""
                /></span>
              </div>
              <div style="display: flex; flex-direction: column">
                <span
                  class="attachmnet_uderline_email"
                  style="
                    font-weight: 400;
                    font-size: 12px;
                    white-space: nowrap;
                    width: 240px;
                    overflow: hidden;
                    text-overflow: ellipsis;
                  "
                  @click="attachmnetname(box.properties.name)"
                >
                  {{ box.properties.name }}
                </span>
              </div>
              <div v-if=" box.loaderData === true ">
          <hlx-loader load-type="horizontal-loop" />
        </div>
            </div>
          </div>
         
          
         
          <slot></slot>
        </div>
        <!-- footer for email -->
        <div class="email_footer">
          <div class="email_footer_left">
            <div>
              <hlx-button
                style="padding: 10px 24px"
                class="primary sm"
                :disabled="
                  (displayValueTo.length > 0 ||
                    displayValueCc.length > 0 ||
                    displayValueBcc.length > 0) &&
                  subjectEmailInput != '' && errorHandule === false &&
                  (filesArrayGet.length > 0 || bodyContentv != '')
                    ? false
                    : true
                "
                @click="sendEmail"
              >
                Send
              </hlx-button>
            </div>
            <div class="email_link">
              <i
                style="font-size: 22px !important"
                class="icon-paperclip-regular"
                @click="triggerFileInput"
              ></i>

              <input
                id="fileUpload"
                ref="fileInput"
                autocomplete="off"
                type="file"
                :accept="fileType"
                name="fileUpload[]"
                style="display: none"
                multiple
                @change="chooseFiles"
              />
            </div>
          </div>

          <div class="email_footer_right">
            <!-- <div class="email_dot">
              <i class="icon-more-vertical-filled"></i>
            </div> -->
            <div class="email_delete" @click="deleteemail">
              <i style="color: #6e6b7b" class="icon-trash-regular"></i>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
// import { MLTAxiosInstance } from "@/config/axiosConfig";
import hlxLabel from "./LabelComponent.vue";
import HlxFileUpload from "./FileUploadComponent.vue";
import HlxTextEditor from "./TexteditorComponent.vue";
import HlxButton from "./ButtonComponent.vue";
import hlxModal from "./ModalwindowComponent.vue";
import hlxTag from "./TagComponent.vue";
import hlxLoader from "./LoaderComponent.vue";

export default {
  name: "HlxEmail",
  components: {
    hlxLoader,
    HlxFileUpload,
    hlxLabel,
    hlxTag,
    HlxTextEditor,
    hlxModal,
    HlxButton,
  },
  props: {
  
    isLoader: {
      type: Boolean,
      default: false,
    },
    loadAttachmnet: {
      type: Boolean,
      default: false,
    },
    recipient: {
      type: Array,
      default: () => {
        return [];
      },
    },
    type: {
      type: String,
      default: "",
    },
    bodyContent: {
      type: String,
      default: "",
    },
    subjectContent: {
      type: String,
      default: "",
    },
    defaultTo: {
      type: String,
      default: "",
    },
    fileType: {
      type: String,
      default: ".json,.xlsx,.doc,.pdf,.txt,.jpg,.jpeg,.png",
    },
    fileSizeLimit: {
      type: String,
      default: "1 GB",
    },
    show: {
      type: Boolean,
      default: false,
    },
  },
  emits: [
    "upload-data",
    "close",
    "at-input",
    "recipient-detail",
    "body-content",
    "attachments",
    "updated-email-content",
    "attachment-name",
  ],
  data() {
    return {
      // buttonDisabled:true,
      backgrounStyleupload: {
        backgroundColor: "",
        bacgroundtTextColor: "#000000",
        border: false,
        borderColor: "#A8A8A8",
        TextfontSize: 12,
      },
      filesArrayData:[],
      valid_modal_active:false,
      bodyContentv: "",
      defaultContain: false,
      isExpanded: false,
      enteredValues: [],
      overflowCount: 0,
      filesArray: [],
      filesArrayGet: [],
      inputValue: "",
      showAllEmail: false,
      filterValue: "",
      delete_modal_active: false,
      showEmailDescriptionTo: false,
      showEmailDescriptionCc: false,
      showEmailDescriptionBcc: false,
      showEmailModal: false,
      showTo: true,
      showCc: false,
      showBcc: false,
      toEmailInput: "",
      ccEmailInput: "",
      bccEmailInput: "",

      defaultValue: "",
      firstTwoValue: "",
      moreValueToCc: 0,
      moreValueBcc: 0,
      componentKey: 0,
      template: "",
      notification: {},
      tagValueTo: [],
      tagValueCc: [],
      tagValueBcc: [],
      displayValueTo: [],
      displayValueCc: [],
      displayValueBcc: [],
      allTagsValue: [],
      allTagsValuetest: [],
      dummy: [],
      moreMessage: "",
      isSendButtonDisabled: true,
      errorHandule: false,
      wrongMailTo: "",
      wrongMailCc: "",
      wrongMailBcc: "",
      combinedMessage:""
    };
  },
  // computed: {
  //   isSendButtonDisabled() {
  //     return this.allTagsValuetest.length === 0;
  //   },
  // },

  // || this.template.trim() === "";

  watch: {
    loadAttachmnet: {
      handler(val) {
        console.log(this.filesArrayData ,"before false");
        
        if(val === false){
          this.filesArrayData = this.filesArrayData.map(item => ({ ...item, loaderData: false }));
        }
        console.log(val,"valisLoadervar",this.filesArrayData);
      },
      immediate: true,
      deep: true,
    },

    toEmailInput: {
      handler(val) {
        if (val !== "") {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(val)) {
            this.errorHandule=true
          }
          this.filteredData = this.filterData(val);
          this.showEmailDescriptionTo = true;
        } else {
          this.showEmailDescriptionTo = false;
          this.errorHandule=false
        }
      },
      immediate: true,
      deep: true,
    },
    allTagsValuetest: {
      handler(val) {
        console.log(val.length);
        if (val.length > 0) {
          this.isSendButtonDisabled = false;
        } else {
          this.isSendButtonDisabled = true;
        }
      },
      immediate: true,
      deep: true,
    },
    tagValueBcc: {
      handler(val) {
        console.log(val.length);
        this.moreValueBcc = val.length;
      },
      immediate: true,
      deep: true,
    },
    subjectContent: {
      handler(val) {
        this.subjectEmailInput = val;
      },
      immediate: true,
      deep: true,
    },
    bodyContent: {
      handler(val) {
        this.bodyContentv = val;
      },
      immediate: true,
      deep: true,
    },
    show: {
      handler(val) {
        console.log(val, "showval");
        this.showEmailModal = val;
        if (val == true) {
          if (this.defaultValue) {
            this.defaultContain = true;
            this.isSendButtonDisabled = false;
            this.tagValueTo.unshift(this.defaultValue.email);
            this.displayValueTo.unshit(this.defaultValue);
          }
        }
        val = false;
      },
      immediate: true,
      deep: true,
    },
    filesArray: {
      handler(val) {
        console.log(val, "filesarray");

        this.updatedemailcontent();
        this.filesArrayGet = val;
        console.log(this.filesArrayGet, "filesArrayGet");
      },
      immediate: true,
      deep: true,
    },
    ccEmailInput: {
      handler(val) {
        if (val !== "") {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(val)) {
            this.errorHandule=true
          }
          this.filteredData = this.filterData(val);
          this.showEmailDescriptionCc = true;
        } else {
          this.errorHandule=false
          this.showEmailDescriptionCc = false;
        }
      },
      immediate: true,
      deep: true,
    },
    firstTwoValue: {
      handler(val) {
        console.log(val);
      },
      immediate: true,
      deep: true,
    },

    defaultTo: {
      handler(val) {
        if (val) {
          if (val.length > 0) {
            this.defaultValue = val;
            this.tagValueTo.push(val);
            this.displayValueTo.push({ email: val, name: val });
            this.defaultContain = true;
            this.isSendButtonDisabled = false;
          }
        }
      },
      immediate: true,
      deep: true,
    },

    bccEmailInput: {
      handler(val) {
        if (val !== "") {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(val)) {
            this.errorHandule=true
          }
