<template>
  <li
    @mousedown="mouseDown"
    @mouseup="mouseUp"
    @mousemove="mouseMove"
    @dblclick="mouseDown"
  >
    <hlx-card
      :seperator="false"
      :card_title="false"
      :card_footer="false"
      :hover="inventory === true
      ? false
      : true"
    >
      <template #card-body>
        <div
          v-if="type === 'Hierarchy' || type === 'orderTree'"
          style="
            padding: 0;
            height: 55px;
            width: 298px;
            align-items: center;
            display: flex;
            justify-content: center;
          "
          class="tree-card-upc"
        >
          <div class="header grid card" style="padding: 0 9px; width: 100%">
            <span v-if="type === 'Hierarchy'" :style="avatarStyle">
              {{ initials }}
            </span>
            <span style="padding: 0 0 0 9px">
              <span v-if="nodes['@type'] === 'parentOrder'"
                ><i class="icon-buildings-alt-regular tree-iconegold odertree"
              />
            </span>
              <span v-if="nodes['@type'] === 'serviceOrder'"
                ><i class="icon-buildings-regular tree-icone2 odertree"
              /></span>
              <span v-if="nodes['@type'] === 'subOrder'"
                ><i class="icon-buildings-regular tree-icone3 odertree"
              /></span>
            </span>
            <span
              style="
                width: 80%;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                display: flex;
                flex-direction: column;
                align-items: flex-start;
                justify-content: flex-start;
              "
            >
              <span
                class="Card-name-tree"
                :class="{ 'margin-6px': hasDescriptionOrAddress }"
                style="
                  display: flex;
                  justify-content: space-evenly;
                  min-width: 63px;
                  max-width: 200px;

                  text-decoration: none !important;
                "
              >
                <span style="display: flex; justify-content: center">
                  <span
                    style="
                      font-size: 12px;
                      text-align: left;
                      display: -webkit-box;
                      -webkit-line-clamp: 2;
                      -webkit-box-orient: vertical;
                      overflow: hidden;
                    "
                  >
                    <span v-if="type === 'Hierarchy'">{{
                      nodes?.customName
                    }}</span>

                    <span @click="oderdetails">
                      <span
                        v-if="nodes['@type'] === 'parentOrder'"
                        class="carddetailoderdetails"
                        @click="odermove(nodes)"
                        >{{ orderCompanyName }}</span
                      >
                      <span
                        v-else
                        class="carddetailoderdetails"
                        @click="odermove(nodes)"
                        >{{ orderChildCompanyName }}</span
                      >
                    </span>
                  </span>
                  <span
                    v-if="type === 'Hierarchy'"
                    :style="{
                      display: HierarchytagName !== '' ? 'block' : 'none',
                    }"
                  >
                    <hlx-label
                      class="primary sm"
                      style="margin-left: 6px; height: 14px; font-size: 8px"
                    >
                      {{ HierarchytagName }}
                    </hlx-label>
                  </span>
                  <span v-if="type === 'orderTree'" style="margin-left: 8px">
                    <span v-if="nodes['@type'] === 'parentOrder'">
                      <hlx-label class="primary sm">
                        {{ nodes.status }}
                      </hlx-label>
                      <!-- :options="{'background-color':'rgba(173, 196, 255, 0.5)','text-color':'rgba(68, 119, 255, 1)','border-color':'rgba(68, 119, 255, 1)'}" -->
                    </span>
                    <span v-else>
                      <hlx-label class="primary sm">
                        {{ orderStatusName }}
                      </hlx-label></span
                    >
                  </span>
                </span>
              </span>

              <span
                v-if="type === 'Hierarchy'"
                class="card-address"
                style="
                  font-size: 8px;
                  display: -webkit-box;
                  max-width: 179px;
                  -webkit-line-clamp: 2;
                  -webkit-box-orient: vertical;
                  overflow: hidden;
                  text-align: left;
                  font-family: Opensans;
                  font-weight: 100;
                "
              >
                <span>{{ Hierarchydescription }}</span>
              </span>
              <span
                v-if="type === 'orderTree' && nodes['@type'] != 'parentOrder'"
                class="card-address statusforoder"
                style="
                  margin-top: 5px;
                  font-size: 8px;
                  font-weight: 400;
                  line-height: 6.81px;
                  text-align: left;
                  text-underline-position: from-font;
                  text-decoration-skip-ink: none;
                  color: rgba(166, 166, 166, 1);
                "
              >
                {{ orderChildAddressName }}
              </span>
            </span>
          </div>
          <div
            v-for="key in Object.keys(nodes.data ? nodes.data : {}) || []"
            :key="key"
            class="grid"
          >
            <span class="key">{{ key }}:</span>
            <span class="value">{{ nodes.data[`${key}`] }}</span>
          </div>
          <span
            :class="
              nodes.child !== undefined && nodes.child?.length > 0
                ? 'collapseIcon'
                : ''
            "
            style="right: 48.3% !important"
            ><i
              :ref="'icon-' + unique"
              :class="
                nodes.child !== undefined && nodes.child?.length > 0
                  ? collapse
                  : ''
              "
              @click="nodesToggler"
            ></i
          ></span>
          <i
            v-if="type == 'Hierarchy'"
            class="tempp-container icon-more-vertical-filled"
            :class="{ ' active-context': show_add_menu === true }"
            @click.stop="showHierarchy(nodes)"
          >
          </i>
          <span
            style="
              position: absolute;
              left: 247px;
              top: 66px;
              display: flex;
              justify-content: center;
              align-items: center;
            "
          >
            <i v-if="type == 'Hierarchy'" class="icon-user-circle-regular"></i>
            <span
              v-if="type == 'Hierarchy'"
              style="font-size: 12px; margin-left: 3px"
            >
              {{ Hierarchycontactcount }}
            </span>
            <span v-if="nodes.quantity">
              <i
                v-if="
                  nodes['@type'] === 'resourceOrderItem' ||
                  nodes['@type'] === 'serviceOrderItem' ||
                  nodes['@type'] === 'productOrderItem'
                "
                class="icon-shopping-cart-regular"
              ></i>
              <span
                v-if="
                  nodes['@type'] === 'resourceOrderItem' ||
                  nodes['@type'] === 'serviceOrderItem' ||
                  nodes['@type'] === 'productOrderItem'
                "
                style="font-size: 12px; margin-left: 3px"
              >
                {{ nodes.quantity }}
              </span>
            </span>
          </span>
          <hlx-context-menu
            :displaydata="displayvalue"
            class="tree-context-menu"
            style="
                z-index: 1000 !important;
                width: 125px;
                position: absolute;
                height: (add_context_options.length>1) ? 119px : 50px;
                overflow: hidden;
              "
            :options="add_context_options"
            :show="show_add_menu"
            @chosen="fromAddContextMenuHierarchy($event, nodes)"
          ></hlx-context-menu>
        </div>
        <div
          v-if="type != 'Hierarchy' && type != 'orderTree'"
          style="
            padding: 0;
            height: 55px;
            width: 200px;
            align-items: center;
            display: flex;
            justify-content: center;
          "
          class="tree-card-upc"
        >
          <div
            class="header grid card"
            style="padding: 0 9px"
            @click.stop="card"
          >
            <span>
             <i
                :class="inventory == true
                  ? 'icon-package-regular tree-icon4'
                  : nodes?.service?.icones"
              ></i></span>
            <span class="Card-name-tree" @click="cardDetail">{{
              nodes?.specification?.name || nodes?.offerName?.name?.name ||  nodes?.offerName?.name
            }}</span>
          </div>
          <div
            v-for="key in Object.keys(nodes.data ? nodes.data : {}) || []"
            :key="key"
            class="grid"
          >
            <span class="key">{{ key }}:</span>
            <span class="value">{{ nodes.data[`${key}`] }}</span>
          </div>
          <span
            :class="
              nodes.child !== undefined && nodes.child?.length > 0
                ? 'collapseIcon'
                : ''
            "
            >
            <i
              :ref="'icon-' + unique"
              :class="
                nodes.child !== undefined && nodes.child?.length > 0
                  ? collapse
                  : ''
              "
              @click="nodesToggler"
            ></i
          ></span>
          <i
            class="tempp-container icon-more-vertical-filled"
            :class="{ ' active-context': show_add_menu === true }"
            @click.stop="show(nodes)"
          >
          </i>

          <hlx-context-menu
            :displaydata="displayvalue"
            class="tree-context-menu"
            style="
                z-index: 1000 !important;
                width: 115px;
                position: absolute;
                height: (add_context_options.length>1) ? 119px : 50px;
                overflow: hidden;
              "
            :options="add_context_options"
            :show="show_add_menu"
            @chosen="fromAddContextMenu($event, nodes)"
          ></hlx-context-menu>
        </div>

        <!-- </div> -->
      </template>
    </hlx-card>

    <div v-if="isOpen" :class="'tree-child-card'" style="z-index: 1000">
      <div class="inner-card-details">
        <i :class="nodes?.service?.icones + ' size-tree-icon'"></i>
        <b style="font-size: 14px">{{ nodes?.specification?.name }}</b>

        <!-- <hlx-status
          v-if=" == 'Active'"
          :type="'active'"
          >
        </hlx-status>
        <hlx-label
          v-else-if="nodes?.specification?.lifecycleStatus == 'Launched'"
          class="success sm"
        >
          Launched
        </hlx-label>
        <hlx-label
          v-else-if="nodes?.specification?.lifecycleStatus == 'Retired'"
          class="info sm"
        >
          Retired
        </hlx-label>
        <hlx-label
          v-else-if="nodes?.specification?.lifecycleStatus == 'Rejected'"
          class="error sm"
        >
          Rejected
        </hlx-label>
        <hlx-label
          v-else-if="nodes?.specification?.lifecycleStatus == 'Obsolete'"
          class="warning sm"
        >
          Obsolete
        </hlx-label>
        <hlx-label
          v-else-if="nodes?.specification?.lifecycleStatus == 'In test'"
          class="warning sm"
          :options="{
            'background-color': '#F4F4F4',
            'text-color': '#4B4B4B',
            'border-color': '#4B4B4B',
          }"
        >
          In test
        </hlx-label>
        <hlx-label
          v-else-if="nodes?.specification?.lifecycleStatus == 'In design'"
          class="warning sm"
          :options="{
            'background-color': '#FFFDE9',
            'text-color': '#897E06',
            'border-color': '#897E06',
          }"
        >
          In design
        </hlx-label>
        <hlx-label
          v-else
          class="warning sm"
          :options="{
            'background-color': '#E9ECFF',
            'text-color': '#354592',
            'border-color': '#354592',
          }"
        >
          In study
        </hlx-label> -->
      </div>

      <span v-if="nodes?.specification?.lifecycleStatus?.length > 0">
        <hlx-status :type="nodes?.specification?.lifecycleStatus" />
      </span>
      <br />

      <p
        style="
          margin: 10px 0;
          font-size: 12px;
          display: -webkit-box;
          -webkit-line-clamp: 3;
          -webkit-box-orient: vertical;
          overflow: hidden;
        "
      >
        {{ nodes?.specification?.description }}
      </p>

      <span :style="getStyleObject">
        <b :style="getStyleObject" style="font-size: 14px">Characteristics</b>

        <div
          v-if="
            nodes?.service?.name === 'Customer Facing Service' &&
            nodes?.specification?.serviceSpecCharacteristic !== undefined &&
            nodes?.specification?.serviceSpecCharacteristic?.length > 0
          "
          style="margin: 10px 0; font-size: 12px"
        >
          <div class="tree-dot">
            <span style="font-size: 1rem; display: flex; align-items: center">
              <span
                style="
                  width: 8px;
                  height: 8px;
                  background: rgba(84, 189, 149, 1);
                  border-radius: 100px;
                "
              >
              </span>
              <span style="font-size: 12px !important; margin-left: 5px">{{
                nodes?.specification?.serviceSpecCharacteristic[0]?.name
              }}</span></span
            >
          </div>

          <div class="tree-dot">
            <span style="font-size: 1rem; display: flex; align-items: center">
              <span
                style="
                  width: 8px;
                  height: 8px;
                  background: rgba(84, 189, 149, 1);
                  border-radius: 100px;
                "
              >
              </span>
              <span style="font-size: 12px !important; margin-left: 5px">{{
                nodes?.specification?.serviceSpecCharacteristic[1]?.name
              }}</span></span
            >
          </div>
        </div>
        <div
          v-if="
            (nodes?.service?.name === 'Logical Resource' ||
              nodes?.service?.name === 'Physical Resource' ||
              nodes?.service?.name === 'Resource Facing Service' ||
              nodes?.service?.name === 'Resource Facing Service') &&
            nodes?.specification?.resourceSpecCharacteristic?.length > 0
          "
          style="margin: 10px 0; font-size: 12px"
        >
          <div class="tree-dot">
            <span style="font-size: 1rem; display: flex; align-items: center">
              <span
                style="
                  width: 8px;
                  height: 8px;
                  background: rgba(84, 189, 149, 1);
                  border-radius: 100px;
                "
              >
              </span>
              <span style="font-size: 12px !important; margin-left: 5px">{{
                nodes?.specification?.resourceSpecCharacteristic[0]?.name
              }}</span></span
            >
          </div>

          <div class="tree-dot">
            <span style="font-size: 1rem; display: flex; align-items: center">
              <span
                style="
                  width: 8px;
                  height: 8px;
                  background: rgba(84, 189, 149, 1);
                  border-radius: 100px;
                "
              >
              </span>
              <span style="font-size: 12px !important; margin-left: 5px">{{
                nodes?.specification?.resourceSpecCharacteristic[1]?.name
              }}</span></span
            >
          </div>
        </div>
      </span>
      <div
        class="link-tree"
        style="font-size: 12px; color: rgba(67, 129, 249, 1)"
        @click="Cardemit(nodes)"
      >
        View details
      </div>
    </div>
    <div
      v-if="oderdetail && type === 'orderTree'"
      :class="'ordertreedetilecard'"
      style="z-index: 1000"
    >
      <div class="inner-card-details oder-card-details">
        <span>
          <span v-if="nodes['@type'] === 'productOrder'"
            >
            <i class="icon-box-check-regular tree-icone3 odertree"/>
          </span>
          <span v-if="nodes['@type'] === 'serviceOrder'"
            ><i class="icon-users-group-alt-regular tree-icone2 odertree"
          /></span>
          <span v-if="nodes['@type'] === 'resourceOrder'"
            ><i class="icon-shield-bolt-regular tree-icon odertree"
          /></span>
          <span
            v-if="
              nodes['@type'] === 'resourceOrderItem' ||
              nodes['@type'] === 'serviceOrderItem' ||
              nodes['@type'] === 'productOrderItem'
            "
          >
            <i class="icon-tag-regular tree-icon-Logical odertree"
          /></span>
        </span>

        <span v-if="type === 'orderTree' && nodes.state">
          <hlx-status :type="nodes.state" />
        </span>
      </div>
      <b style="font-size: 14px">
        <span
          v-if="
            nodes['@type'] === 'productOrder' ||
            nodes['@type'] === 'serviceOrder' ||
            nodes['@type'] === 'resourceOrder'
          "
          @click="odermove(node)"
          >{{ nodes?.displayID }}</span
        >
        <span
          v-if="
            nodes['@type'] === 'resourceOrderItem' ||
            nodes['@type'] === 'serviceOrderItem'
          "
          @click="odermove(node)"
          >{{ nodes?.specification?.name }}</span
        >
        <span v-if="nodes['@type'] === 'productOrderItem'" @click="odermove(node)">{{
          nodes.productOffering.name
        }}</span></b
      >
      <div
        v-if="nodes?.specification?.category?.length > 0"
        style="font-size: 9px; color: rgba(112, 112, 112, 1)"
      >
        {{
          nodes?.specification?.category[
            nodes?.specification?.category.length - 1
          ]
        }}
      </div>
      <br />

      <div
        style="
          margin: 10px 0;
          font-size: 10px;
          display: -webkit-box;
          -webkit-line-clamp: 3;
          -webkit-box-orient: vertical;
          overflow: hidden;
        "
      >
        {{ nodes?.description }}
      </div>
      <div
        class="link-tree"
        style="font-size: 12px; color: rgba(67, 129, 249, 1)"
        @click="Cardemit(nodes)"
      >
        View details
      </div>
    </div>

    <ul v-if="nodes && nodes.child && nodes.child?.length > 0" :ref="'ul'">
      <hlx-tree-child-v2
        v-for="child in nodes.child || nodes.child[0]"
        :key="child"
        :nodes="child"
        :type="type"
        :parent-name="parentName"
        @card-nodes="Cardemit"
        @context="fromAddContextMenuHierarchy"
      >
        <slot></slot>
      </hlx-tree-child-v2>
    </ul>
  </li>
</template>

<script>
import hlxCard from "./CardsComponent.vue";
import hlxContextMenu from "../components/Treecontextmenu.vue";
import HlxStatus from "../components/StatusComponent.vue";
import HlxLabel from "../components/LabelComponent.vue";
// import { HlxLabel } from 'production/dist/cjs';
export default {
  name: "HlxTreeChildV2",
  components: {
    HlxLabel,
    hlxCard,
    HlxStatus,
    hlxContextMenu,
  },

  props: {
    optionvalue: {
      type: Object,
      default: function () {
        return {
          Link_a_child: "Link a child",
          Remove: "Remove",
          Delete: "Delete",
          Add: "Add",
          Edit: "Edit",
        };
      },
    },
    type: {
      type: String,
      default: () => "product",
    },
    nodes: {
      type: Object,
      default: () => {
        return {};
      },
    },
    isDraggable: {
      type: Boolean,
      default() {
        return false;
      },
    },
    inventory:{
      type: Boolean,
      default() {
        return false;
      },
    },
    displayvalue: {
      type: String,
      default: "label",
    },
    parentInst: {
      type: String,
      default: undefined,
    },
    parentName: {
      type: String,
      default: "",
    },
  },
  emits: [
    "context",
    "mouseeDown",
    "mouseeUp",
    "mouseeMove",
    "delete-nodes",
    "card-nodes",
    "currentdata",
    "specification",
    "currenteditdata",
    "ParentDetail",
  ],
  data() {
    return {
      oderdetail: false,
      isOpen: false,
      collapse: "icon-minus-circle-filled downIcon",
      unique: "",
      treeUnique: "",
      disableTreeButton: "",
      add_context_options: [],
      show_add_menu: false,
      HierarchytagName: "",
      Hierarchydescription: "",
      Hierarchycontactcount: 0,
    };
  },

  computed: {
    labeloderStyles() {
      const state = this.order.state?.toLowerCase();
      const type = this.order.type?.toLowerCase();

      let styles = {
        backgroundColor: null,
        color: null,
        borderColor: null,
      };

      if (state === "completed") {
        styles.backgroundColor = "#54bd95";
        styles.color = "white";
        styles.borderColor = "#54bd95";
      }

      if (type === "product order") {
        styles.backgroundColor = "rgba(173, 196, 255, 0.5)";
        styles.borderColor = "rgba(68, 119, 255, 1)";
        styles.color = "rgba(68, 119, 255, 1)";
      } else if (type === "service order") {
        styles.backgroundColor = "rgba(246, 218, 237, 0.7)";
        styles.borderColor = "rgba(237, 104, 187, 1)";
        styles.color = "rgba(237, 104, 187, 1)";
      } else if (type === "resource order") {
        styles.backgroundColor = "rgba(101, 155, 185, 0.23)";
        styles.color = "rgba(66, 144, 189, 1)";
        // Assuming no border-color specified for 'resource order'
      } else if (type === "order item") {
        styles.backgroundColor = "rgba(175, 140, 233, 0.45)";
        styles.color = "#af8ce9";
        // Assuming no border-color specified for 'order item'
      }

      return styles;
    },
    orderCompanyName() {
      const company = this.nodes.relatedParty.find(
        (item) => item["@type"] === "orderCompany"
      );
      return company ? company.name : "Not Found";
    },
    orderStatusName() {
      const company = this.nodes.relatedParty.find(
        (item) => item["@type"] === "site"
      );
      return company ? company.status : "Not Found";
    },
    orderChildCompanyName() {
      const company = this.nodes.relatedParty.find(
        (item) => item["@type"] === "site"
      );
      console.log(company, "company");
      return company ? company.siteName : "Not Found";
    },
    orderChildAddressName() {
      const company = this.nodes.relatedParty.find(
        (item) => item["@type"] === "site"
      );
      console.log(company, "company");
      return company
        ? company.siteAddress.characteristic.description
        : "Not Found";
    },
    hasDescriptionOrAddress() {
      return this.nodes.state || this.Hierarchydescription;
    },
    initials() {
      const firstTwoWords = this.nodes?.tradingName?.split(" ")?.slice(0, 2);
      return firstTwoWords
        ?.map((word) => word.charAt(0))
        ?.join("")
        ?.toUpperCase();
    },
    avatarStyle() {
      const backgroundColor = this.generateColor(this?.HierarchytagName);
      return {
        width: `35px`,
        height: `35px`,
        borderRadius: "50%",
        background: backgroundColor,
        color: "#ffffff", // Customize the text color
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontSize: `15px`,
      };
    },
    getStyleObject() {
      return {
        display:
          (this.nodes?.service?.name === "Customer Facing Service" &&
            this.nodes?.specification?.serviceSpecCharacteristic?.length > 0) ||
          ((this.nodes?.service?.name === "Logical Resource" ||
            this.nodes?.service?.name === "Physical Resource" ||
            this.nodes?.service?.name === "Resource Facing Service" ||
            this.nodes?.service?.name === "Resource Facing Service") &&
            this.nodes?.specification?.resourceSpecCharacteristic?.length > 0)
            ? "block"
            : "none",
      };
    },
  },
  watch: {
    type: {
      handler(val) {
        // // console.log (this.nodes);
        if (val === "product") {
          this.placeholderValue = "Choose the service";
        } else if (val === "resource") {
          this.placeholderValue = "Type of resource";
        } else if (val === "service") {
          this.placeholderValue = "Choose resource";
        } else {
          this.placeholderValue = "Type of resource";
        }
      },
      immediate: true,
      deep: true,
    },
    inventory:{
      handler(val){
        val
      },
      immediate:true,
      deep:true
    }
  },

  mounted() {
    this.unique =
      Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
    window.addEventListener("click", this.hide);
    window.addEventListener("click", this.odercard);

    const postalAddressContactMedium = this.nodes?.contactMedium?.find(
      (medium) => medium?.mediumType === "postalAddress"
    );

    console.log(postalAddressContactMedium, "postalAddressContactMedium");
    if (postalAddressContactMedium) {
      this.HierarchytagName =
        postalAddressContactMedium?.characteristic["@type"];
      this.Hierarchydescription =
        postalAddressContactMedium?.characteristic?.description;
      const postCode = postalAddressContactMedium?.postCode;

      console.log("City:", this.HierarchytagName);
      console.log("Country:", this.Hierarchydescription);
      console.log("Post Code:", postCode);
    } else {
      console.log("No contactMedium with mediumType 'postalAddress' found.");
    }

    const relatedParty = this.nodes.relatedParty;
    if (relatedParty && relatedParty.length > 0) {
      let count = 0;
      for (let i = 0; i < relatedParty.length; i++) {
