<template>
  <div class="light">
    <div class="calendar">
      <div class="calendar-header">
        <div class="year-picker">
          <span id="prev-year" class="year-change">
            <p style="margin: 0px"><i class="icon-angle-left-regular"></i></p>
          </span>
          <span>
            <span id="month-picker" class="month-picker">February</span>
            <span id="year">2021</span>
          </span>
          <span id="next-year" class="year-change">
            <p style="margin: 0px"><i class="icon-angle-right-regular"></i></p>
          </span>
        </div>
      </div>
      <div class="calendar-body">
        <div class="calendar-week-day">
          <div>
            <!-- SUN -->
             {{ staticDataDays?.sun }}
          </div>
          <div>
            <!-- MON -->
             {{ staticDataDays?.mon }}
          </div>
          <div>
            <!-- TUE -->
            {{ staticDataDays?.tue }}
          </div>
          <div>
            <!-- WED -->
            {{ staticDataDays?.wed }}
          </div>
          <div>
            <!-- THU -->
            {{ staticDataDays?.thu }}
          </div>
          <div>
            <!-- FRI -->
            {{ staticDataDays?.fri }}
          </div>
          <div>
            <!-- SAT -->
            {{ staticDataDays?.sat }}
          </div>
        </div>
        <div class="calendar-days" @click="hlxUIKitCalendarOnClickHandler"></div>
      </div>
      <!-- <div class="calendar-footer">

        </div> -->
      <div class="month-list"></div>
    </div>
  </div>
</template>

<script>

export default {
  name: "HlxCalendar",
  props: {
    disableWeekend: {
      type: Boolean,
      default: false,
    },
    dateFormatLanguage: {
      type: String,
      default: 'en',
    },
    event: {
      type: [Array, PointerEvent],
      default: () => {
        return [];
      },
    },
    preValue: {
      type: [Date, String],
      default: "",
    },
    startYear: {
      type: Number,
      default: 1950,
    },
    endYear: {
      type: Number,
      default: 2050,
    },
    holidayList: {
      type: Array,
      default: () => {
        return [];
      },
    },
  },
  emits: ["selectedDate","formattedDate"],
  data() {
    return {
      selectedMonth: "",
      selectedYear: "",
      selectedDay: "",
      formattedDate: "",


      staticDataDays: localStorage.getItem('dayDataShort') ? JSON.parse(localStorage.getItem('dayDataShort')) : {
        sun: "SUN", mon: "MON", tue: "TUE", wed: "WED", thu: "THU", fri: "FRI", sat: "SAT"
      },

      monthNames: localStorage.getItem('monthDataLong') ? JSON.parse(localStorage.getItem('monthDataLong')) : [
        "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"
      ],

    };
  },
  async mounted() {

    console.log("days111:::", JSON.parse(localStorage.getItem('dayDataShort')));
    console.log("monthLong111:::", JSON.parse(localStorage.getItem('monthDataLong')));

    // if (localStorage.getItem('monthDataLong')) {
    //   this.monthNames = JSON.parse(localStorage.getItem('monthDataLong'))
    //   console.log("local::", this.monthNames);
    // } else {
    //   console.log("not local::");
      
    //   let monthNames = await this.languageTransferArray(this.monthNames, this.dateFormatLanguage)
    //   this.monthNames = monthNames;
    //   localStorage.setItem('monthDataLong', JSON.stringify(monthNames))
    // }

    // if (localStorage.getItem('dayDataShort')) {
    //   this.staticDataDays = JSON.parse(localStorage.getItem('dayDataShort'))
    //   console.log("local::", this.staticDataDays);
    // } else {
    //   console.log("not local::");
      
    //   let staticDataDays = await this.translateStaticDataDays(this.staticDataDays, this.dateFormatLanguage)
    //   this.staticDataDays = staticDataDays;
    //   localStorage.setItem('dayDataShort', JSON.stringify(staticDataDays))
    // }







    console.log(this.event, 'cal eve', this.dateFormatLanguage)
    const calendar = document.querySelector(".calendar");
    const light = document.querySelector(".light");
    calendar.clientY = this.event.clientY;
    light.right = this.event.clientX + "px";
    const monthNames = [
      "January",
      "February",
      "March",
      "April",
      "May",
      "June",
      "July",
      "August",
      "September",
      "October",
      "November",
      "December",
    ];
    const yearNames = [];
    let startYear = this.startYear;
    const endYear = this.endYear;
    while (startYear <= endYear) {
      yearNames.push(startYear++);
    }
    const monthList = calendar.querySelector(".month-list");

    yearNames.forEach((e, index) => {
      const month = document.createElement("div");
      month.innerHTML = `<div data-month="${index}" id="year${index}" class="idd${e}">${e}</div>`;
      const currDate = new Date();
      let y = currDate.getFullYear();
      y += 1;
      if (e === y) {
        document
          .getElementById("year" + (index - 1))
          .classList.add("theme-background");
        document.getElementById("year" + (index - 1)).style.color = "white";
      }
      month.querySelector("div").onclick = () => {

        monthList.classList.remove("show");
        currYear.value = e;
        this.selectedMonth = currMonth.value;
        this.selectedYear = currYear.value;
        // if (monthUP) {
          this.generateCalendar(currMonth.value, currYear.value);
        // }
      };
      monthList.appendChild(month);
    });

    // const monthPicker = calendar.querySelector('#month-picker')
    const yearPicker = calendar.querySelector("#year");

    yearPicker.onclick = () => {
      monthList.classList.add("show");
      document.querySelector('.selected-curr-year')?.classList?.remove('selected-curr-year')
      let item = document.querySelector('.idd'+this.selectedYear)
      item.classList.add('selected-curr-year')
      // let item2 = document.querySelector('.theme-background')
      // item2.classList.remove('theme-background')
      // item.style.color = 'white'
      // item.style.backgroundColor = '#265E4B'
      // localStorage.setItem("calendarScroll", 600);
      // monthList.scrollTo(0, localStorage.getItem("calendarScroll"));
      item.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };
    // monthPicker.onclick = () => {
    //   monthList.classList.add('show')
    // }
    let currDate = "";
    if (this.preValue === "") {
      currDate = new Date();
    } else {
      const d = this.preValue.split("-");
      currDate = new Date(d[2], d[1] - 1, d[0]);
    }
    const currMonth = { value: currDate.getMonth() };
    const currYear = { value: currDate.getFullYear() };
    this.selectedMonth = currMonth.value;
    this.selectedYear = currYear.value;
    // if (monthUP) { 
      this.generateCalendar(currMonth.value, currYear.value);      
    // }
    const calendarHeight = document.querySelector(".calendar");
    if (calendarHeight.offsetHeight === 340) {
      // calendarHeight.style.marginTop = "-35px";
    } else {
      calendarHeight.style.marginTop = "0px";
    }
    document.querySelector("#prev-year").onclick = () => {
      if (monthNames[currMonth.value] === "January") {
        currMonth.value = 11;
        --currYear.value;
      } else {
        --currMonth.value;
      }
      this.selectedMonth = currMonth.value;
      this.selectedYear = currYear.value;
      // if (monthUP) { 
        this.generateCalendar(currMonth.value, currYear.value);
      // }
      const calendarHeight = document.querySelector(".calendar");
      if (calendarHeight.offsetHeight === 340) {
        // calendarHeight.style.marginTop = "-35px";
      } else {
        calendarHeight.style.marginTop = "0";
      }
    };

    document.querySelector("#next-year").onclick = () => {
      const calendarHeight = document.querySelector(".calendar");
      if (monthNames[currMonth.value] === "December") {
        currMonth.value = 0;
        ++currYear.value;
      } else {
        ++currMonth.value;
      }
      this.selectedMonth = currMonth.value;
      this.selectedYear = currYear.value;
      // if (monthUP) {        
        this.generateCalendar(currMonth.value, currYear.value);
      // }
      if (calendarHeight.offsetHeight === 340) {
        // calendarHeight.style.marginTop = "-35px";
      } else {
        calendarHeight.style.marginTop = "0";
      }
    };

    // Get all elements with the class "prevent-click"
    const elements = document.querySelectorAll(".disable-weekend");

    // Add event listeners to prevent their @click events
    elements.forEach((element) => {
      element.addEventListener("click", (event) => {
        event.stopPropagation(); // Prevent event propagation
        event.preventDefault(); // Prevent the default click behavior
        // Optionally, you can add your custom logic here
      });
    });


    
    


  },
  methods: {
    async translateStaticDataDays(staticDataDays1, targetLanguage) {
    const daysArray = Object.keys(staticDataDays1).map(day => staticDataDays1[day]);

    // Translate the array of days
    const translatedDays = await this.languageTransferArray(daysArray, targetLanguage);

    // Map the translated days back into the same object structure
    const translatedStaticDataDays = Object.keys(staticDataDays1).reduce((result, day, index) => {
        result[day] = translatedDays[index];
        return result;
    }, {});

    console.log("poiuytrewq:",translatedStaticDataDays);
    
    return translatedStaticDataDays;
},
    hlxUIKitCalendarOnClickHandler($event) {
      try {
        console.log($event?.target?.innerHTML ?? null, 'inner html');
      if ($event.target.innerHTML !== "") {
        if ($event.target.innerHTML.length <= 2) {
          if ($event.target.innerHTML.length < 2) {
            this.selectedDay = 0 + $event.target.innerHTML;
          } else {
            this.selectedDay = $event.target.innerHTML;
          }
          //   this.selectedMonth += 1
          //   this.selectedMonth = String(this.selectedMonth)
          //   if (this.selectedMonth < 10) {
          //     this.selectedMonth = '0' + String(this.selectedMonth+1)
          //   }
          //   console.log(this.selectedMonth)
          this.selectedDate =
            this.selectedDay +
            "-" +
            (this.selectedMonth + 1 < 10
              ? "0" + String(this.selectedMonth + 1)
              : this.selectedMonth + 1) +
            "-" +
            this.selectedYear;


          this.$emit("selectedDate", this.selectedDate);
          
        }
      }
      } catch (error) {
        console.error('ui kit calendar:: ', error);
        this.$emit("selectedDate", null);
      }
      
    },

    isLeapYear(year) {
      return (
        (year % 4 === 0 && year % 100 !== 0 && year % 400 !== 0) ||
        (year % 100 === 0 && year % 400 === 0)
      );
    },
    getFebDays(year) {
      return this.isLeapYear(year) ? 29 : 28;
    },
    generateCalendar(month, year) {
    console.log(month, year, 'jui');

    const calendar = document.querySelector(".calendar");
    const calendarDays = calendar.querySelector(".calendar-days");
    const calendarHeaderYear = calendar.querySelector("#year");

    const daysOfMonth = [
        31,
        this.getFebDays(year),
        31,
        30,
        31,
        30,
        31,
        31,
        30,
        31,
        30,
        31,
    ];

    calendarDays.innerHTML = "";

    let currDate = "";
    if (this.preValue === "") {
        currDate = new Date();
    } else {
        const d = this.preValue.split("-");
        currDate = new Date(d[2], d[1] - 1, d[0]);
    }

    if (!year) year = currDate.getFullYear();
      const monthNames = this.monthNames;
    const currMonth = `${monthNames[month]}`;
    const monthPicker = calendar.querySelector("#month-picker");

    monthPicker.innerHTML = currMonth;
    calendarHeaderYear.innerHTML = year;

    // Get the first day of the month
    const firstDay = new Date(year, month, 1);

    for (let i = 0; i <= daysOfMonth[month] + firstDay.getDay() - 1; i++) {
        const day = document.createElement("div");
        if (i >= firstDay.getDay()) {
          
            day.classList.add("calendar-day-hover");
            const dayOfMonth = i - firstDay.getDay() + 1;

            if (dayOfMonth > 0 && dayOfMonth <= daysOfMonth[month]) {
                const x = `${dayOfMonth}-${month + 1}-${year}`;
                day.classList.add(x);
                console.log('fkoko', x);
                day.id = "calender-day";

                if (this.holidayList.includes(x)) {
                    day.classList.remove("calendar-day-hover");
                    day.classList.add("disable-weekend");
                }
                day.innerHTML = dayOfMonth;
                if (
                    dayOfMonth === currDate.getDate() &&
                    year === currDate.getFullYear() &&
                    month === currDate.getMonth()
                ) {
                    day.classList.add("curr-date");
                }
            }
        }
        calendarDays.appendChild(day);
    }

    if (this.disableWeekend === true) {
        const currMnthDays = document.querySelector(".calendar-days").children;
        const weekEnds = [0, 6, 7, 13, 14, 20, 21, 27, 28, 34, 35];
        for (const day in weekEnds) {
            if (
                currMnthDays[weekEnds[day]] &&
                currMnthDays[weekEnds[day]].innerHTML !== ""
            ) {
                currMnthDays[weekEnds[day]].classList.remove("calendar-day-hover");
                currMnthDays[weekEnds[day]].classList.add("disable-weekend");
            }
        }
    }
},

  },
};
</script>

<style lang="scss"></style>
