<template>
  <hlx-modal
    :modal-active="showError"
    :height="'220px'"
    :width="'400px'"
    :modal="true"
    @close="showError = false"
  >
    <template #header>
      <div style="margin-left: 0px">
        {{ matchFromStatic(warningModalTitle) }}
      </div>
    </template>
    <template #content>
      <div class="modal-content">
        <p>
          {{ matchFromStatic(warningModalContent) }}
        </p>
      </div>
    </template>
    <template #footer>
      <hlx-button
        class="primary sm"
        style="margin-left: 16px"
        @click="showError = false"
        >{{ matchFromStatic("Close") }}</hlx-button
      >
    </template>
  </hlx-modal>
  <div
  v-if="type === 'multi-upload-main'"
  style="
      margin-top: 15px;
      padding-top: 21px;
      display: flex;
      height: 100%;
      flex-direction: column;
      "
  >
    <div  v-if="!uploaded && !readOnly" class="main-content-body-upload" style="height: 170px">
      <div
        v-if="!uploaded && !readOnly"
        v-cloak
        class="upload-panel"
        @drop.prevent="addFiles"
        @dragover.prevent
      >
        <div class="panel-items" :style="{
          cursor: readOnly ? 'not-allowed' : 'pointer',
          pointerEvents: readOnly ? 'none' : 'auto'
        }">
          <i
            class="icon-cloud-upload-regular"
            style="font-size: 50px; color: #ccc"
            @click="triggerFileInput"
          ></i>
          <span
            class="drag-text"
            style="font-size: 12px; color: #191a15"
            @click="triggerFileInput"
          >
            <span style="color: #54bd9a">
              <!-- Select files -->
              {{ labelValue?.Select_files || "" }}
            </span>
            <!-- or drag and
                    drop -->
            {{ labelValue?.or_drag_and_drop || "" }}
          </span>
          <span
            class="or-text"
            style="font-size: 12px; margin-top: 8px; color: #a6a6a6"
            @click="triggerFileInput"
          >
            {{ fileType.replaceAll(".", " ").toUpperCase() }}
            <!-- Max -->
            {{ labelValue?.Max || "" }}
            {{ fileSizeLimit.toUpperCase() }}
          </span>
          <input
            id="fileUpload"
            ref="fileInput"
            autocomplete="off"
            type="file"
            :accept="fileType"
            name="fileUpload[]"
            style="display: none"
            multiple
            @change="chooseFiles"
          />
        </div>
      </div>
      <div v-if="uploaded" class="upload-panel containere">
        <!-- Display uploaded files -->
      </div>
      <span class="upload-footer">{{ err_msg }}</span>
    </div>
    <div class="box-attachment-supplier-parent" style = "overflow-y: unset !important">
      <div
        v-for="(box, index) in filesArray"
        :key="index"
        class="single_line_upload"
        style="margin: 10px 0"
      >
