<template>
  <div
    v-if="disabled == false"
    :id="'inline-multi-select' + unique"
    class="inline-multi-select"
    :style="error == true ? 'border-color:#ff5050 !important' : ''"
    @click="optioncontainer1"
  >
    <div class="inline-input-section">
      <div
        v-show="dropdownclose == true"
        :id="'inline-multi-select-tag-value' + unique"
        class="inline-multi-select-tag-value"
      >
        <div
          v-for="(i, index) in showselectedvalue"
          :id="'custom-multi-select-tag-value' + unique"
          :key="index"
          class="custom-multi-select-tag-value"
        >
          <hlx-tag
            :limit="false"
            class="multiselect-inline-tag-option"
            @tag-close.stop="removed(i[propValue])"
            >{{ i[label] }}</hlx-tag
          >
        </div>
      </div>
      <input
        v-show="dropdownopen == true"
        :id="'inline-select-input' + unique"
        ref="multiselect"
        v-model="inlinemultisearchvalue"
        type="text"
        @keypress="multiselectsearch"
        @input="multiselectType"
        @keyup.enter="addvalue"
      />
      <div
        v-show="inline_count_value != 0"
        class="inline-multi-select-count-section"
      >
        <div
          class="inline-multi-select-count"
          :data-tooltip="tooltipdata"
          :data-tooltip-location="tooltipposition"
        >
          {{ "+" + inline_count_value }}
        </div>
      </div>
      <i :id="'arrow' + unique" class="icon-angle-down-regular"></i>
      <p
        v-show="
          dropdownclose == true &&
          showselectedvalue.length == 0 &&
          required == true
        "
        class="custom-multi-select-title1"
      >
        {{ label_Value }}<span class="asterik">{{ "*" }}</span>
      </p>
      <p
        v-show="
          dropdownclose == true &&
          showselectedvalue.length == 0 &&
          required == false
        "
        class="custom-multi-select-title1"
      >
        {{ label_Value }}
      </p>
      <p
        v-show="
          labelAnimation == true &&
          required == false &&
          (dropdownopen == true || showselectedvalue.length != 0)
        "
        class="custom-multi-select-title"
        :style="error == true ? 'Color:#ff5050 !important' : ''"
      >
        {{ label_Value }}
      </p>
      <p
        v-show="
          labelAnimation == true &&
          required == true &&
          (dropdownopen == true || showselectedvalue.length != 0)
        "
        class="custom-multi-select-title"
        :style="error == true ? 'Color:#ff5050 !important' : ''"
      >
        {{ label_Value }}
      </p>
      <p v-if="error == true" class="customerror">{{ customError }}</p>
      <!-- <div class="inline-multi-select-placeholder">
      {{label_Value}}
    </div> -->
    </div>
    <hlx-overlay
      v-show="dropdownopen == true"
      :key="componentkey"
      :search="inlinemultisearchvalue"
      :show="dropdownopen"
      :top="containertop"
      :left="containerleft"
      :width="containerwidth"
      :conditionvalue="250"
      :conditiondown="45"
      :conditionup="10"
    >
      <template #overlay>
        <div class="inline-multi-select-option-container">
          <span class="input-container232" style="overflow-x: none !important">
            <div class="whole-checkbox">
              <label
                v-if="showSelectAll == true && multiselectsearch1.length > 0"
                class="check-container"
                @mouseover="hoverSelectAll"
                @mouseleave="unHoverSelectAll"
                >{{ "Select all" }}
                <i
                  v-if="partiallySelected == true"
                  class="icon-minus-regular partially-checked"
                ></i>
                <input
                  style="margin-right: 15px"
                  type="checkbox"
                  class="selcet"
                  :class="'select-all' + unique"
                  :checked="false"
                  @click="selectAll"
                />
                <span
                  :id="'select-all-checkmark' + unique"
                  class="checkmark"
                  @mouseover="hoverSelectAll"
                  @mouseleave="unHoverSelectAll"
                ></span>
              </label>
              <div
                v-for="element in multiselectsearch1"
                :key="element.id"
                class="checkbox-container"
              >
                <label class="check-container">
                  <span class="ellipsis">{{ element[label] }}</span>
                  <input
                    :id="'check-drag' + unique"
                    type="checkbox"
                    :checked="element.checked"
                    :disabled="element.disabled"
                    class="check-correct"
                    :class="'check-drag' + unique"
                    @click="checkItem(element, $event)"
                  />
                  <span class="checkmark"></span>
                </label>
              </div>
            </div>
          </span>
          <div v-if="filterSelect == true" class="custom-multi-select-footer">
            <hlx-button class="secondary-success sm">Cancel</hlx-button>
            <hlx-button class="primary sm" @click="filtersave">Save</hlx-button>
          </div>
        </div>
      </template>
    </hlx-overlay>
  </div>

