<script>
// import hlxInput from "./InputComponent.vue";
import hlxTag from "./TagComponent.vue";
import hlxButton from "./ButtonComponent.vue";
import hlxOverlay from "../components/OverlayComponent.vue";

export default {
  name: "HlxMultiSelect",
  components: {
    // hlxInput,
    hlxTag,
    hlxButton,
    hlxOverlay,
  },
  props: {
    refreshKey: {
      type: Number,
      default: 0,
    },
    tooltipposition: {
      type: String,
      default: "right",
    },
    error: {
      type: Boolean,
      default: false,
    },
    customError: {
      type: String,
      default: "",
    },

    scrollClassname: {
      type: String,
      default: "",
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    filterSelect: {
      type: Boolean,
      default: false,
    },
    options: {
      type: Array,
      default: () => {
        return [];
      },
    },
    placeholder: {
      type: String,
      default: "Select",
    },
    label: {
      type: String,
      default: "name",
    },
    propValue: {
      type: String,
      default: "value",
    },
    preValue: {
      type: Array,
      // eslint-disable-next-line vue/require-valid-default-prop
      default: [],
    },
    labelAnimation: {
      type: Boolean,
      default: true,
    },
    required: {
      type: Boolean,
      default: false,
    },
  },
  emits: [
    "add-data",
    "custom-change",
    "selected-value",
    "tagRemoveData",
    "selected-array",
    "custom-error-emit-value",
    "arrow-click",
    "typeValue",
    "inputValue",
    "removed-value",
  ],
  data() {
    return {
      eachtagWidth: 0,
      tooltipdata: "",
      containerwidth: 0,
      containertop: 0,
      containerleft: 0,
      componentkey: 0,
      filtereddata: [],
      hovered: false,
      preeval: [],
      preval: [],
      count22: 0,
      removereferencedata: [],
      multiselectdata: [],
      searchoptions: [],
      tagwidth: 0,
      disabledvalue: [],
      inlinemultisearchvalue: "",
      dropdownclose: true,
      dropdownopen: false,
      all: false,
      unique: Date.now().toString(36) + Math.random().toString(36).substr(2, 5),
      multi_select_inline_tag_array: [],
      multi_select_inline_tag_value: 0,
      inputvalue: "",
      multi_select_inline_count_show: false,
      multi_select_inline_count_value: 0,
      multiselecttagvalue: 0,
      showselectedvalue: [],
      returndata: [],
      multiselectinlineoptions: [],
      tagarray: [],
      dropdowncontainer: false,
      placeholder_value: "",
      title: false,
      label_Value: "",
      top: 45,
      left: 1,
      count: 0,
      inline_count_value: 0,

      showSelectAll: true,
      select_all: false,
      all_checked: true,
      partially_checked: false,
      atleastOne: false,
      typing: false,
      // intelliData: [],
      small: true,
      showMandatory: false,
      optionsD: [],
      duplicatedata: [],
    };
  },
  computed: {
    partiallySelected() {
      return this.partially_checked;
    },
    multiselectsearch1() {
      const data = [...this.optionsD];
      let data1 = [];
      this.$emit("inputValue", this.inlinemultisearchvalue);
      if (this.inlinemultisearchvalue != "" && this.inlinemultisearchvalue) {
        data1 = data.filter((e) => {
          if (
            e[this.label]
              .toString()
              .toLowerCase()
              .includes(this.inlinemultisearchvalue.toLowerCase())
          ) {
            this.checkBox();
            // this.showSelectAll = false
            return e;
          }
        });
        // this.switchdropdown(data1)
        return data1;
      } else {
        this.checkBox();
        // this.showselectall()
        // this.switchdropdown(data)
        // console.log('hi',data);
        return data;
      }
    },
  },
  watch: {
    refreshKey: {
      handler(val) {
        console.log(val, "keyyyyyyyyy");
        this.$nextTick(() => {
          if (
            document.querySelector(
              "#inline-multi-select-tag-value" + this.unique
            )
          ) {
            this.tagwidth = document
              .querySelector("#inline-multi-select-tag-value" + this.unique)
              .getBoundingClientRect().width;
            // this.resizedata()
            // console.log(this.tagwidth,'this.tagwidth');
          }
        });
      },
      immediate: true,
      deep: true,
    },
    placeholder: {
      handler(val) {
        this.placeholder_value = val;
      },
      immediate: true,
      deep: true,
    },
    placeholder_value: {
      handler(val) {
        this.label_Value = val;
      },
      immediate: true,
      deep: true,
    },
    optionsD: {
      handler(val) {
        val;
        this.resizedata();
      },
      immediate: true,
      deep: true,
    },
    inlinemultisearchvalue: {
      handler(val) {
        this.$emit("typeValue", val);
        // console.log(val,"multiselectType");
      },
      immediate: true,
      deep: true,
    },
    label: {
      handler(val) {
        val;
      },
      immediate: true,
      deep: true,
    },
    propValue: {
      handler(val) {
        val;
      },
      immediate: true,
      deep: true,
    },
    inline_count_value: {
      handler(val) {
        val;
      },
      immediate: true,
      deep: true,
    },
    tagwidth: {
      handler(val) {
        if (val != 0) {
          this.$nextTick(() => {
            if (
              document.querySelector(
                "#inline-multi-select-tag-value" + this.unique
              )
            ) {
              this.tagwidth = document
                .querySelector("#inline-multi-select-tag-value" + this.unique)
                .getBoundingClientRect().width;
              this.resizedata();
            }
          });
        }
      },
      immediate: true,
      deep: true,
    },
    options: {
      handler(val) {
        val.forEach((e) => {
          if (e.checked === undefined) {
            e.checked = false;
            e.disabled = false;
          }
        });
        let count = 0;
        this.$nextTick(() => {
          if (document.querySelector(".select-all" + this.unique)) {
            document.querySelector(".select-all" + this.unique).checked = false;
          }
        });
        this.preeval.forEach((e) => {
          this.options.forEach((ele) => {
            if (ele[this.propValue] == e) {
              ele.checked = true;
              count = count + 1;
            }
          });
        });
        if (count == this.optionsD.length) {
          this.all_checked = true;
          this.partially_checked = false;
          this.$nextTick(() => {
            if (document.querySelector(".select-all" + this.unique)) {
              // console.log('kslksk');
              document.querySelector(
                ".select-all" + this.unique
              ).checked = true;
            }
          });
        } else if (count != this.optionsD.length && count > 0) {
          this.partially_checked = true;
          this.all_checked = false;
          this.$nextTick(() => {
            //     document.getElementById(
            //   "select-all-checkmark" + this.unique
            // ).classList.add('partially-checked-color')
            document.getElementById(
              "select-all-checkmark" + this.unique
            ).style.background = "#54bd95";
            document.getElementById(
              "select-all-checkmark" + this.unique
            ).style.border = "1px solid #54bd95";
          });
        } else {
          this.all_checked = false;
          this.partially_checked = false;
        }
        this.optionsD = JSON.parse(JSON.stringify([...val]));
      },
      immediate: true,
      deep: true,
    },
    preeval: {
      handler(val) {
        if (val.length != 0) {
          val.forEach((e) => {
            this.options.forEach((ele) => {
              if (ele[this.propValue] == e) {
                ele.checked = true;
              } else {
                ele.checked = false;
              }
            });
          });
        }
      },
      immediate: true,
      deep: true,
    },
    preValue: {
      handler(val) {
        if (val.length != 0) {
          this.preeval = JSON.parse(JSON.stringify([...val]));
        }
      },
      immediate: true,
      deep: true,
    },
    showselectedvalue: {
      handler(val) {
        if (val.length != 0) {
          this.title = true;
        }
      },
      immediate: true,
      deep: true,
    },
    // inlinemultisearchvalue:{
    //   handler()
    //   {
    //       // if(val != '')
    //       // {
    //       //   this.multiselectsearch()
    //       // }
    //   },
    //   immediate:true,
    //   deep:true
    // },
    // returnvalue:{
    //   handler(val)
    //   {
    //        val
    //   },
    //   immediate:true,
    //   deep:true
    // }
  },
  mounted() {
    // this.multiselectsearch()
    this.$nextTick(() => {
      if (
        document.querySelector("#inline-multi-select-tag-value" + this.unique)
      ) {
        this.tagwidth = document
          .querySelector("#inline-multi-select-tag-value" + this.unique)
          .getBoundingClientRect().width;
      }
    });
    window.addEventListener("resize", () => {
      // console.log(document.querySelector("#inline-multi-select-tag-value" + this.unique));
      if (
        document.querySelector("#inline-multi-select-tag-value" + this.unique)
      ) {
