  methods: {
    sanitizeEmailInput(value) {
      if (!value) return "";

      let email = value.trim().replace(/^["'<\s]+|[>"'\s]+$/g, "");

      if (email.toLowerCase().startsWith("mailto:")) {
        email = email.substring(7);
      }

      if (email.includes("?")) {
        email = email.split("?")[0];
      }

      return email;
    },
    handlePaste(event) {
      // console.log("event", event.target.value);

      // event.preventDefault(); // block raw paste
      // const pastedText = (event.clipboardData || window.clipboardData).getData(
      //   "text"
      // );
      this.value = this.sanitizeEmailInput(event.target.value);
    },
    camelToReadable(text) {
      if (!text) return "";
      return text
        .replace(/([a-z])([A-Z])/g, "$1 $2") // insert space before capital letters
        .replace(/([A-Z])([A-Z][a-z])/g, "$1 $2") // handle capital groupings like "metaID"
        .replace(/^./, (str) => str.toUpperCase()); // capitalize first letter
    },
    parseMixedDate(val) {
      try {
        if (typeof val !== "string" || !val.trim()) return "";

        const frenchFull = JSON.parse(
          localStorage.getItem("monthDataLong") || "[]"
        );
        const frenchShort = JSON.parse(
          localStorage.getItem("monthDataShort") || "[]"
        );
        const englishLong = [
          "January",
          "February",
          "March",
          "April",
          "May",
          "June",
          "July",
          "August",
          "September",
          "October",
          "November",
          "December",
        ];
        const englishShort = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];

        val = val.trim();

        // ✅ ISO 8601 format
        if (/^\d{4}-\d{2}-\d{2}T/.test(val)) {
          const isoDate = new Date(val);
          return isNaN(isoDate) ? "" : isoDate;
        }

        // ✅ Numeric date: dd-mm-yyyy or dd/mm/yyyy
        // eslint-disable-next-line no-useless-escape
        const numericMatch = val.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
        if (numericMatch) {
          const day = parseInt(numericMatch[1], 10);
          const month = parseInt(numericMatch[2], 10) - 1;
          const year = parseInt(numericMatch[3], 10);
          return new Date(year, month, day);
        }

        // ✅ Text-based date
        val = val.replace(/,/g, "");
        const parts = val.split(" ");

        let day, monthRaw, year;
        if (parts.length === 3) {
          if (!isNaN(parts[0])) {
            day = parseInt(parts[0], 10);
            monthRaw = parts[1];
            year = parseInt(parts[2], 10);
          } else if (!isNaN(parts[1])) {
            monthRaw = parts[0];
            day = parseInt(parts[1], 10);
            year = parseInt(parts[2], 10);
          } else {
            return "";
          }
        } else {
          return "";
        }

        const normalize = (str) =>
          str
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .toLowerCase();
        const monthNorm = normalize(monthRaw);

        const findMonthIndex = (arr) =>
          arr.findIndex((m) => normalize(m) === monthNorm);

        let monthIndex = findMonthIndex(frenchFull);
        if (monthIndex === -1) monthIndex = findMonthIndex(frenchShort);
        if (monthIndex === -1)
          monthIndex = englishLong.findIndex(
            (m) => m.toLowerCase() === monthNorm
          );
        if (monthIndex === -1)
          monthIndex = englishShort.findIndex(
            (m) => m.toLowerCase() === monthNorm
          );

        if (monthIndex === -1) return "";

        return new Date(year, monthIndex, day);
      } catch (err) {
        return "";
      }
    },

    getNestedLookupValue(obj, path) {
      return path?.split(".").reduce((acc, key) => acc && acc[key], obj);
    },
    validateTelephone() {
      const validTelephonePattern = /^\(\d{3}\) \d{3}-\d{4}$/;
      const invalidNumbers = ["(000) 000-0000"];

      if (!validTelephonePattern.test(this.formattedTelephone)) {
        this.input_error_message = "Please enter a valid telephone number";
        if (this.singleBorder) {
          document.getElementById(
            "input-field" + this.unique
          ).style.borderBottom = "1px solid " + "var(--hlx-color-error)";
        } else {
