<template>
  <!-- {{parentelementwidth}}{{parentHeight}} -->
  <div
    v-if="type === 'slide-preview-upload'"
    :style="{
      display: 'flex',
      gap: '2%',

      flexDirection: position === 'horizontal' ? 'column-reverse' : 'row',
    }"
  >
    <span
      v-show="options.length > 0"
      class="carousel-container"
      style="height: 450px"
      :style="{
        height: position === 'horizontal' ? 'auto' : `${parentWidth}px`,
      }"
    >
      <span
        class="carousel"
        :style="{
          transform:
            position === 'horizontal'
              ? `translateX(${offset}px)`
              : `translateY(${offset}px)`,

          display: position === 'horizontal' ? 'flex' : 'flex',
          flexDirection: position === 'horizontal' ? 'row' : 'column',
          flexFlow: position === 'horizontal' ? 'row ' : 'column',
          gap: `1.5%`,
        }"
      >
        <div
          v-for="(option, index) in options"
          :key="index"
          class="slideuplod-label"
          @click="selectOption(option[value], option)"
        >
          <div
            @mouseenter="hoverOption(option[value], option)"
            @mouseleave="leavemouse(option[value], option)"
          >
            <img
              class="imagePreve"
              :class="{ selected: selectedOption === option[value] }"
              :src="option[value]"
              :alt="image"
              accept="image/*"
              :height="height"
              :width="width"
              style="object-fit: contain"
            />
          </div>
        </div>
      </span>

      <span v-if="position === 'horizontal'">
        <span v-if="!atStart">
          <button class="prev" @click="moveCarousel(-1.2, 'previe')">
            <i class="icon-angle-left-filled"></i>
          </button>
        </span>
        <span v-if="atlast === true && options.length > 4">
          <button class="next" @click="moveCarousel(1.2, 'next')">
            <i class="icon-angle-right-regular"></i>
          </button>
        </span>
      </span>

      <span v-if="position === 'vertical'">
        <span v-if="!atStart">
          <button
            class="prevtop"
            @click="previewImagvertival(-1.2, 'previe', options)"
          >
            <i class="icon-angle-up-filled"></i>
          </button>
        </span>
        <span v-if="atlast === true && options.length > 4">
          <button
            class="nextbuttom"
            @click="previewImagvertival(1.2, 'next', options)"
          >
            <i class="icon-angle-down-filled"></i>
          </button>
        </span>
      </span>
    </span>
    <div>
      <img
        class="imagePreve"
        :src="previewImag"
        :alt="image"
        accept="image/*"
        :height="parentWidth"
        :width="parentheight"
        :style="{ height: `${parentheight}px`, width: `${parentWidth}px` }"
        style="object-fit: contain"
      />
    </div>
  </div>

  <div
    v-if="type === 'slide-upload'"
    class="main-content-body-upload"
    :style="
      position === 'horizontal'
        ? 'display: flex; gap: 2%;'
        : 'display: flex;     flex-direction: row-reverse;gap:2%'
