<script>
import hlxButton from "./ButtonComponent.vue";
import hlxModal from "./ModalwindowComponent.vue";
import HlxImportProgress from "../components/ImportProgressComponent.vue";
import HlxLoader from "../components/LoaderComponent.vue";

// import hlxAlertNotification from "../components/AlertComponent.vue";
export default {
  name: "HlxFileUpload",
  components: {
    // hlxAlertNotification,
    hlxButton,
    hlxModal,
    HlxImportProgress,
    HlxLoader,
  },
  // props:['fileType','fileSizeLimit','customIcon', 'type'],
  props: {
    setDefalt: {
      type: Boolean,
      default: false,
    },

    labelValue: {
      type: Object,
      default: function () {
        return {
          Select_files: "Select files",
          Upload_file: "Upload file",
          Upload: "Upload",
          Select_file: "Select file",
          or_drag_and_drop: "or drag and drop",
          Drag_and_drop_your_files: "Drag and drop your files",
          Choose_file: "Choose file",
          or: "or",
          Max: "Max",
          Cancel: "Cancel",
        };
      },
    },
    loader: {
      type: Boolean,
      default: false,
    },
    isLoader: {
      type: Boolean,
      default: false,
    },
    width: {
      type: String,
      default: "100",
    },
    height: {
      type: String,
      default: "100",
    },
    position: {
      type: String,
      default: "horizontal",
    },
    styleBackground: {
      type: Object,
      default: function () {
        return {
          backgroundColor: "transparent",
          bacgroundtTextColor: "Black",
          border: false,
          borderColor: "#d8d8d8",
          TextfontSize: 24,
        };
      },
    },
    parentWidth: {
      type: String,
      default: "400",
    },
    parentHeight: {
      type: String,
      default: "400",
    },
    prefferedImage: {
      type: String,
      default: "Bar-Headed Goose",
    },

    value: {
      type: String,
      default: "data",
    },
    profileIcon: {
      type: String,
      default: "icon-user-regular",
    },
    options: {
      type: Array,
      default: () => [],
    },
    sliderOptions: {
      type: Array,
      default: () => [],
    },
    preValue: {
      type: String,
      default: "",
    },
    showEllipsis: {
      type: Boolean,
      default: true,
    },
    readOnly: {
      type: Boolean,
      default: false,
    },
    nameDisplay: {
      type: String,
      default: () => "",
    },
    nameBackgroundColor: {
      type: String,
      default: () => "white",
    },
    nameSize: {
      type: Number,
      default: 15,
    },
    backgroundColor: {
      type: String,
      default: () => "transparent",
    },
    uploadtype: {
      type: String,
      default: () => "Square",
    },

    preset: {
      type: Object,
      default: () => ({}),
    },
    src: {
      type: String,
      default: () => "",
    },
    presetFiles: {
      type: Array,
      default: () => [],
    },
    fileType: {
      type: String,
      default: "",
    },
    regularFileName: {
      type: String,
      default: "",
    },
    fileSizeLimit: {
      type: String,
      default: "",
    },
    customIcon: {
      type: String,
      default: "",
    },
    icon: {
      type: String,
      default: "",
    },
    content: {
      type: String,
      default: "",
    },
    type: {
      type: String,
      default: "regular",
    },
    profilePicPreview: {
      type: String,
      default: "",
    },
  },
  emits: [
    "fileData",
    "previewFile",
    "deleteFile",
    "filesArray",
    "deleteImage",
    "downloadImage",
    "native-data",
    "default-image",
    "selected-value",
    "hovered-value",
  ],
  data() {
    return {
      overflow: false,
      previewImages: [],
      previewImagesevent: [],
      currentIndex: 0,
      offset: 0,
      selectedOption: "",
      hoverImg: "",
      selecImg: "",
      activeDefaultIndex: null,

      profilePicPreviewData: "",
      uploaded: false,
      singleUploader: false,
      profileuploaded: false,
      fileItems: [],
      progress: [0, 0, 0],
      display: [true, true, true],
      modal_active: false,
      unique: Date.now().toString(36) + Math.random().toString(36).substr(2, 5),
      err_msg: "",
      buploadfile: false,
      auploadfile: false,
      file_data: {},
      files: [],
      file_name: "",
      uploaddata: false,
      disablebutton: true,
      ftype: true,
      fsize: "",
      fsizee: true,
      fact: "",
      preview_data: "",
      cancelled: false,
      hover: false,
      isValid: false,
      isLoading: false,
      count: 0,
      totallengthpreview: 0,
      atlast: false,
    };
  },
  computed: {
    atStart() {
      return this.currentIndex === 0;
    },
    atEnd() {
      return this.currentIndex === this.previewImages.length - 1;
    },
    previewImag() {
      if (this.hoverImg.length > 0 && this.type === "slide-preview-upload") {
        return this.hoverImg;
      } else if (
        this.selecImg.length > 0 &&
        this.type === "slide-preview-upload"
      ) {
        return this.selecImg;
      } else {
        return "data:image/png;base64,"; // Handle the case when neither hoverImg nor selecImg has a value
      }
    },
  },

  watch: {
    options: {
      handler(val) {
        if (
          window.innerWidth > this.width * val.length &&
          this.type === "slide-preview-upload"
        ) {
          this.overflow = true;
        } else {
          this.overflow = false;
        }
        // console.log(
        //   val,
        //   val.length,
        //   this.width * val.length,
        //   window.innerWidth,
        //   this.overflow,
        //   "previewImages"
        // );

        if (val.length > 0) {
          val.sort((a, b) => (b.preferred ? 1 : 0) - (a.preferred ? 1 : 0));
          this.initializeSelectedOption();
        }
      },
      immediate: true,
      deep: true,
    },
    isLoader: {
      handler(val) {
        console.log(val, "valisLoadervar");

        if (val === false) {
          this.previewImages = this.previewImages.map((item) => ({
            ...item,
            loaderData: false,
          }));
          this.singleUploader = false;
        }
      },
      immediate: true,
      deep: true,
    },
    preValue: {
      handler(val) {
        // Find the object in options array where value matches preValue
        const selectedObject = this.options.find(
          (option) => option[this.value] === val
        );
        if (selectedObject && this.type === "slide-preview-upload") {
          this.selectedOption = selectedObject[this.value];
        } else {
          // If no match is found, set selectedOption to empty string
          this.selectedOption = "";
        }
      },
      immediate: true, // This ensures that the watcher runs immediately when the component is created
    },
    previewImages: {
      handler(val) {
        if (window.innerWidth > this.width * val) {
          this.overflow = true;
        } else {
          this.overflow = false;
        }
      },
      immediate: true,
      deep: true,
    },
    sliderOptions: {
      handler(val) {
        this.previewImages = val;
      },
      immediate: true,
      deep: true,
    },
    prefferedImage: {
      handler(val) {
        this.activeDefaultIndex = val;
      },
      immediate: true,
      deep: true,
    },
    nameDisplay: {
      handler(val) {
        const firstTwoWords = val.split(" ").slice(0, 2);
        this.initials = firstTwoWords
          .map((word) => word.charAt(0))
          .join("")
          .toUpperCase();
        // console.log(val, "ll", this.initials);
      },
      deep: true,
      immediate: true,
    },
    regularFileName: {
      handler(val) {
        this.file_name = val;
      },
      deep: true,
      immediate: true,
    },
    preset: {
      handler(val) {
        if (val != undefined && Object.keys(val).length > 0) {
          // console.log(val);
          this.uploaded = true;
          this.file_name = val?.name;
          this.preview_data = val?.data;
          if (this.type == "upc-regular") {
            var doc = this.preview_data;
            // console.log(doc, "mfskm");
            setTimeout(() => {
              var imageData = doc; // Your binary data string here

              // Decode the Base64-encoded data
              var binaryData = atob(imageData);

              // Create a Blob object representing the image data
              var blob = new Blob([binaryData], { type: "image/png" });

              // Create a data URL representing the Blob object
              var imageUrl = URL.createObjectURL(blob);

              // Create an image element and set its source to the data URL
              var img = document.createElement("img");
              img.src = imageUrl;

              // Append the image to a container element in the HTML document
              document.body.appendChild(img);

              // console.log(doc,"preset")
            }, 300);
          }
          if (this.type == "profile-upload") {
            var doc = this.preview_data;
            // console.log(doc, "mfskm");
            setTimeout(() => {
              var imageData = doc; // Your binary data string here

              // Decode the Base64-encoded data
              var binaryData = atob(imageData);

              // Create a Blob object representing the image data
              var blob = new Blob([binaryData], { type: "image/png" });

              // Create a data URL representing the Blob object
              var imageUrl = URL.createObjectURL(blob);

              // Create an image element and set its source to the data URL
              var img = document.createElement("img");
              img.src = imageUrl;

              // Append the image to a container element in the HTML document
              document.body.appendChild(img);

              // console.log(doc,"preset")
            }, 300);
          }
          if (this.type == "upc-regular-v2") {
            var doc = this.preview_data;
            setTimeout(() => {
              var image = document.getElementById("outputt");

              image.src = URL.createObjectURL(doc);
            }, 300);
          } else if (this.type == "upc-regular-sm") {
            var doc = this.preview_data;
            setTimeout(() => {
              var image = document.getElementById(`output1${this.unique}`);
              // console.log(image,"iiii")
              image.src = URL.createObjectURL(doc);
              // console.log(image,"imgggg")
            }, 300);
          } else if (this.type == "upc-regular-sm-v2") {
            var doc = this.preview_data;
            setTimeout(() => {
              var image = document.getElementById("output-sm");
              // console.log(image,"iiii")
              image.src = URL.createObjectURL(doc);
              // console.log(image,"imgggg")
            }, 300);
          }
        }
      },
      deep: true,
      immediate: true,
    },
    profilePicPreview: {
      handler(val) {
        if (val && val.length > 0 && val != undefined) {
          this.checkImage(this.profilePicPreview);
        }
        this.profilePicPreviewData = val;
        this.profileuploaded = true;
      },
      deep: true,
      immediate: true,
    },
    count: {
      handler(val) {
        const sum = this.totallengthpreview - 4;
        console.log(val, sum);
        if (sum === val) {
          this.atlast = false;
          console.log(this.atlast, "ghjk");
        }
      },
      deep: true,
      immediate: true,
    },

    src: {
      handler(val) {
        if (val.length > 0) {
          this.uploaded = true;
          this.imgSrc = val;
        } else {
          this.uploaded = false;
          this.imgSrc = "";
        }
      },
      deep: true,
      immediate: true,
    },
    imageUrl(newValue, oldValue) {
      if (newValue !== oldValue) {
        this.checkImage();
      }
    },
  },
  mounted() {
    this.initializeSelectedOption();

    if (
      this.profilePicPreview != undefined &&
      this.profilePicPreview.length > 0
    ) {
      this.checkImage(this.profilePicPreview);
      this.profileuploaded = true;
    } else {
      this.profileuploaded = false;
    }
    if (this.preset != undefined && Object.keys(this.preset).length > 0) {
      this.uploaded = true;
      // console.log(this.preset,"preset")
      this.file_name = this.preset?.name;
      this.preview_data = this.preset?.data;
      if (this.type == "upc-regular") {
