        this.err_msg = `Maximum file size is ${this.fileSizeLimit.toUpperCase()}`;
      }
    },
    deleteContainer(event) {
      event.target.parentElement.parentElement.remove();
    },
    previewFile(val) {
      // console.log(this.preview_data);
      this.$emit("previewFile", this.preview_data, val);
    },
    deleteFilename(val) {
      // console.log("ooo");
      this.ftype = true;
      this.fsizee = true;
      this.files = [];
      this.file_data = {};
      this.file_name = "";
      this.auploadfile = false;
      this.buploadfile = true;
      this.disablebutton = true;
      this.$emit("deleteFile", this.file_data, val);
    },
  },

